int buf[N], head = 0, tail = 0;   // head: 맨 앞 칸, tail: 다음에 넣을 칸
void push(int x) { buf[tail] = x; tail = (tail + 1) % N; }
void pop() { head = (head + 1) % N; }
int size() { return (tail - head + N) % N; }

